-- Defensive compatibility for release packages where schema migrations created
-- trg_mml_sub_fields_refresh_paths() but missed this helper function. Seed
-- writes mml_command_sub_fields, so the trigger must be callable first.
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION public.refresh_mml_command_target_paths(p_command_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE public.mml_commands c
    SET target_paths = COALESCE((
            SELECT jsonb_agg(sp.standard_path ORDER BY csf.sort_order)
            FROM public.mml_command_sub_fields csf
            JOIN public.standard_params sp ON sp.id = csf.standard_path_id
            WHERE csf.command_id = p_command_id
              AND csf.deprecated_at IS NULL
        ), '[]'::jsonb),
        tree_node_refs = COALESCE((
            SELECT jsonb_agg(sp.standard_path ORDER BY csf.sort_order)
            FROM public.mml_command_sub_fields csf
            JOIN public.standard_params sp ON sp.id = csf.standard_path_id
            WHERE csf.command_id = p_command_id
              AND csf.deprecated_at IS NULL
        ), '[]'::jsonb),
        updated_at = NOW()
    WHERE c.id = p_command_id;
END;
$$;
-- +goose StatementEnd

