    chapter_code = EXCLUDED.chapter_code,
    instance_arity = EXCLUDED.instance_arity,
    instance_levels = EXCLUDED.instance_levels,
    deprecated_at = NULL,
    deleted_at = NULL,
    updated_at = now();

