WITH rw_fields AS (
  SELECT
    'MOD MML350_DEVICE_REMOTEDEVICELIST__REMOTEDEVICELIST' AS command_code,
    sp.standard_path,
    csf.mml_code,
    csf.label_i18n,
    csf.sort_order,
    CASE WHEN sp.access = 'READ_WRITE' THEN 'RW' ELSE csf.access_type END AS access_type
  FROM public.mml_commands lst
  JOIN public.mml_command_sub_fields csf ON csf.command_id = lst.id
  JOIN public.standard_params sp ON sp.id = csf.standard_path_id
  WHERE lst.command_code = 'LST MML350_DEVICE_REMOTEDEVICELIST__REMOTEDEVICELIST'
    AND lst.source = 'admin'
    AND csf.deprecated_at IS NULL
    AND sp.access = 'READ_WRITE'
)
INSERT INTO public.mml_command_sub_fields (
    command_id, standard_path_id, mml_code, label_i18n,
    default_selected, is_required, sort_order, access_type, is_supported
)
SELECT
    mod_cmd.id,
    sp.id,
    rw.mml_code,
    rw.label_i18n,
    true,
    false,
    rw.sort_order,
    rw.access_type,
    true
FROM rw_fields rw
JOIN public.mml_commands mod_cmd ON mod_cmd.command_code = rw.command_code
JOIN public.standard_params sp ON sp.standard_path = rw.standard_path
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    deprecated_at = NULL,
    is_supported = true,
    updated_at = NOW();

WITH mod_cmd AS (
  SELECT id
  FROM public.mml_commands
  WHERE command_code = 'MOD MML350_DEVICE_REMOTEDEVICELIST__REMOTEDEVICELIST'
)
UPDATE public.mml_commands c
SET target_paths = COALESCE(paths.paths, '[]'::jsonb),
    tree_node_refs = COALESCE(paths.paths, '[]'::jsonb),
    updated_at = NOW()
FROM mod_cmd
LEFT JOIN LATERAL (
  SELECT jsonb_agg(sp.standard_path ORDER BY csf.sort_order, sp.standard_path) AS paths
  FROM public.mml_command_sub_fields csf
  JOIN public.standard_params sp ON sp.id = csf.standard_path_id
  WHERE csf.command_id = mod_cmd.id
    AND csf.deprecated_at IS NULL
) paths ON true
WHERE c.id = mod_cmd.id;

