INSERT INTO public.mml_command_sub_fields (
    command_id, standard_path_id, mml_code, label_i18n, default_selected,
    is_required, sort_order, access_type, is_supported
)
SELECT
    c.id,
    sp.id,
    df.mml_code,
    jsonb_build_object('zh-CN', df.label_zh, 'en-US', df.mml_code),
    true,
    c.operation_type = 'MOD',
    df.sort_order,
    CASE WHEN c.operation_type = 'MOD' THEN 'RW' WHEN sp.access = 'READ_WRITE' THEN 'RW' ELSE 'RO' END,
    true
FROM desired_fields df
JOIN public.mml_commands c ON c.command_code = df.command_code AND c.deprecated_at IS NULL
JOIN public.standard_params sp ON sp.standard_path = df.standard_path
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = now();

WITH target_cmds AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code IN ('LST STD_TRPATH_G01', 'MOD STD_TRPATH_G01', 'LST STD_TRPATH_G02', 'MOD STD_TRPATH_G02', 'LST STD_TRPATH_G03', 'MOD STD_TRPATH_G03', 'LST STD_TRPATH_G04', 'MOD STD_TRPATH_G04', 'LST STD_TRPATH_G05', 'MOD STD_TRPATH_G05', 'LST STD_TRPATH_G06', 'MOD STD_TRPATH_G06', 'LST STD_TRPATH_G07', 'MOD STD_TRPATH_G07', 'LST STD_TRPATH_G08', 'MOD STD_TRPATH_G08', 'LST STD_TRPATH_G09', 'MOD STD_TRPATH_G09', 'LST STD_TRPATH_G10', 'MOD STD_TRPATH_G10', 'LST STD_TRPATH_G11', 'MOD STD_TRPATH_G11', 'LST STD_TRPATH_G12', 'MOD STD_TRPATH_G12', 'LST STD_TRPATH_G13', 'MOD STD_TRPATH_G13', 'LST STD_TRPATH_G14', 'MOD STD_TRPATH_G14')
      AND deprecated_at IS NULL
), refreshed AS (
    SELECT
        t.id,
        COALESCE(jsonb_agg(to_jsonb(sp.standard_path) ORDER BY sf.sort_order, sp.standard_path)
                 FILTER (WHERE sp.standard_path IS NOT NULL), '[]'::jsonb) AS paths
    FROM target_cmds t
    LEFT JOIN public.mml_command_sub_fields sf ON sf.command_id = t.id AND sf.deprecated_at IS NULL
    LEFT JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    GROUP BY t.id
)
UPDATE public.mml_commands c
SET target_paths = r.paths,
    tree_node_refs = r.paths,
    updated_at = now()
FROM refreshed r
WHERE c.id = r.id;

