WITH duplicate_paths(standard_path) AS (
    VALUES
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T300'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T301'),
